const json = (obj, status = 200) =>
  new Response(JSON.stringify(obj, null, 2), {
    status,
    headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' },
  });

export async function onRequestGet(context) {
  const { request, env } = context;
  if (!(await requireAuth(request, env))) return json({ error: 'Not authorized' }, 401);

  const db = env.DB;
  const apply = new URL(request.url).searchParams.get('apply') === '1';

  // 1) Look up current prompt length for every slug (chunks of 50: D1 allows
  //    at most 100 bound parameters per query).
  const current = new Map();
  for (let i = 0; i < FIXES.length; i += 50) {
    const slugs = FIXES.slice(i, i + 50).map(f => f.slug);
    const ph = slugs.map(() => '?').join(',');
    const { results } = await db
      .prepare(`SELECT slug, LENGTH(prompt) AS len FROM prompts WHERE slug IN (${ph})`)
      .bind(...slugs)
      .all();
    for (const r of results) current.set(r.slug, r.len);
  }

  const notFound = FIXES.filter(f => !current.has(f.slug)).map(f => f.slug);
  const alreadyChanged = FIXES.filter(f => current.has(f.slug) && current.get(f.slug) >= 100).map(f => f.slug);
  const eligible = FIXES.filter(f => current.has(f.slug) && current.get(f.slug) < 100);

  if (!apply) {
    return json({
      mode: 'PREVIEW - nothing was changed',
      total_in_file: FIXES.length,
      will_update: eligible.length,
      slug_not_found: notFound,
      already_longer_than_100_chars_skipped: alreadyChanged,
      next_step: 'Open the same URL with ?apply=1 to apply.',
    });
  }

  // 2) Apply in small batches (one D1 call per batch).
  let updated = 0;
  for (let i = 0; i < eligible.length; i += 25) {
    const stmts = eligible.slice(i, i + 25).map(f =>
      db
        .prepare(`UPDATE prompts SET prompt = ?, updated_at = datetime('now') WHERE slug = ? AND LENGTH(prompt) < 100`)
        .bind(f.prompt, f.slug)
    );
    const res = await db.batch(stmts);
    for (const r of res) updated += (r.meta && r.meta.changes) || 0;
  }

  return json({
    mode: 'APPLIED',
    total_in_file: FIXES.length,
    updated,
    slug_not_found: notFound,
    already_longer_than_100_chars_skipped: alreadyChanged,
    note: 'Pages may show the old text for a few minutes (cache). Now delete apply-prompt-fixes.js from the repo.',
  });
}
